1675	func (p *Parser) parseInsertStatement(inTrigger bool, withClause *WithClause) (_ *InsertStatement, err error) {
1676		assert(p.peek() == INSERT || p.peek() == REPLACE)
1677	
1678		var stmt InsertStatement
1679		stmt.WithClause = withClause
1680	
1681		if p.peek() == INSERT {
1682			stmt.Insert, _, _ = p.scan()
1683	
1684			if p.peek() == OR {
1685				stmt.InsertOr, _, _ = p.scan()
1686	
1687				switch p.peek() {
1688				case ROLLBACK:
1689					stmt.InsertOrRollback, _, _ = p.scan()
1690				case REPLACE:
1691					stmt.InsertOrReplace, _, _ = p.scan()
1692				case ABORT:
1693					stmt.InsertOrAbort, _, _ = p.scan()
1694				case FAIL:
1695					stmt.InsertOrFail, _, _ = p.scan()
1696				case IGNORE:
1697					stmt.InsertOrIgnore, _, _ = p.scan()
1698				default:
1699					return &stmt, p.errorExpected(p.pos, p.tok, "ROLLBACK, REPLACE, ABORT, FAIL, or IGNORE")
1700				}
1701			}
1702		} else {
1703			stmt.Replace, _, _ = p.scan()
1704		}
1705	
1706		if p.peek() != INTO {
1707			return &stmt, p.errorExpected(p.pos, p.tok, "INTO")
1708		}
1709		stmt.Into, _, _ = p.scan()
1710	
1711		// Parse table name & optional schema & alias.
1712		if stmt.Table, err = p.parseIdent("table name"); err != nil {
1713			return &stmt, err
1714		}
1715		// Check for schema.table syntax
1716		if p.peek() == DOT {
1717			stmt.Schema = stmt.Table
1718			stmt.Dot, _, _ = p.scan()
1719			if stmt.Table, err = p.parseIdent("table name"); err != nil {
1720				return &stmt, err
1721			}
1722		}
1723		if p.peek() == AS {
1724			stmt.As, _, _ = p.scan()
1725			if stmt.Alias, err = p.parseIdent("alias"); err != nil {
1726				return &stmt, err
1727			}
1728		}
1729	
1730		// Parse optional column list.
1731		if p.peek() == LP {
1732			stmt.ColumnsLparen, _, _ = p.scan()
1733			for {
1734				col, err := p.parseIdent("column name")
1735				if err != nil {
1736					return &stmt, err
1737				}
1738				stmt.Columns = append(stmt.Columns, col)
1739	
1740				if p.peek() == RP {
1741					break
1742				} else if p.peek() != COMMA {
1743					return &stmt, p.errorExpected(p.pos, p.tok, "comma or right paren")
1744				}
1745				p.scan()
1746			}
1747			stmt.ColumnsRparen, _, _ = p.scan()
1748		}
1749	
1750		switch p.peek() {
1751		case VALUES:
1752			stmt.Values, _, _ = p.scan()
1753			for {
1754				var list ExprList
1755				if p.peek() != LP {
1756					return &stmt, p.errorExpected(p.pos, p.tok, "left paren")
1757				}
1758				list.Lparen, _, _ = p.scan()
1759	
1760				for {
1761					expr, err := p.ParseExpr()
1762					if err != nil {
1763						return &stmt, err
1764					}
1765					list.Exprs = append(list.Exprs, expr)
1766	
1767					if p.peek() == RP {
1768						break
1769					} else if p.peek() != COMMA {
1770						return &stmt, p.errorExpected(p.pos, p.tok, "comma or right paren")
1771					}
1772					p.scan()
1773				}
1774				list.Rparen, _, _ = p.scan()
1775				stmt.ValueLists = append(stmt.ValueLists, &list)
1776	
1777				if p.peek() != COMMA {
1778					break
1779				}
1780				p.scan()
1781			}
1782		case SELECT, WITH:
1783			// A select-stmt, which may itself begin with a WITH clause.
1784			if stmt.Select, err = p.parseSelectStatement(false, nil); err != nil {
1785				return &stmt, err
1786			}
1787		case DEFAULT:
1788			stmt.Default, _, _ = p.scan()
1789			if p.peek() != VALUES {
1790				return &stmt, p.errorExpected(p.pos, p.tok, "VALUES")
1791			}
1792			if inTrigger {
1793				return &stmt, p.errorExpected(p.pos, p.tok, "non-DEFAULT VALUES")
1794			}
1795			stmt.DefaultValues, _, _ = p.scan()
1796		default:
1797			return &stmt, p.errorExpected(p.pos, p.tok, "VALUES, SELECT, or DEFAULT VALUES")
1798		}
1799	
1800		// Parse optional upsert clauses. A clause without a conflict target must
1801		// be the last one, so stop looking for more after it.
1802		for p.peek() == ON {
1803			clause, err := p.parseUpsertClause()
1804			if err != nil {
1805				return &stmt, err
1806			}
1807			stmt.UpsertClauses = append(stmt.UpsertClauses, clause)
1808			if !clause.Lparen.IsValid() {
1809				break
1810			}
1811		}
1812	
1813		// Parse optional RETURNING clause.
1814		if p.peek() == RETURNING {
1815			if stmt.ReturningClause, err = p.parseReturningClause(); err != nil {
1816				return &stmt, err
1817			}
1818		}
1819	
1820		return &stmt, nil
1821	}
