1823	func (p *Parser) parseUpsertClause() (_ *UpsertClause, err error) {
1824		assert(p.peek() == ON)
1825	
1826		var clause UpsertClause
1827	
1828		// Parse "ON CONFLICT"
1829		clause.On, _, _ = p.scan()
1830		if p.peek() != CONFLICT {
1831			return &clause, p.errorExpected(p.pos, p.tok, "CONFLICT")
1832		}
1833		clause.OnConflict, _, _ = p.scan()
1834	
1835		// Parse optional indexed column list & WHERE conditional.
1836		if p.peek() == LP {
1837			clause.Lparen, _, _ = p.scan()
1838			for {
1839				col, err := p.parseIndexedColumn()
1840				if err != nil {
1841					return &clause, err
1842				}
1843				clause.Columns = append(clause.Columns, col)
1844	
1845				if p.peek() == RP {
1846					break
1847				} else if p.peek() != COMMA {
1848					return &clause, p.errorExpected(p.pos, p.tok, "comma or right paren")
1849				}
1850				p.scan()
1851			}
1852			clause.Rparen, _, _ = p.scan()
1853	
1854			if p.peek() == WHERE {
1855				clause.Where, _, _ = p.scan()
1856				if clause.WhereExpr, err = p.ParseExpr(); err != nil {
1857					return &clause, err
1858				}
1859			}
1860		}
1861	
1862		// Parse "DO NOTHING" or "DO UPDATE SET".
1863		if p.peek() != DO {
1864			return &clause, p.errorExpected(p.pos, p.tok, "DO")
1865		}
1866		clause.Do, _, _ = p.scan()
1867	
1868		// If next token is NOTHING, then read it and exit immediately.
1869		if p.peek() == NOTHING {
1870			clause.DoNothing, _, _ = p.scan()
1871			return &clause, nil
1872		} else if p.peek() != UPDATE {
1873			return &clause, p.errorExpected(p.pos, p.tok, "NOTHING or UPDATE SET")
1874		}
1875	
1876		// Otherwise parse "UPDATE SET"
1877		clause.DoUpdate, _, _ = p.scan()
1878		if p.peek() != SET {
1879			return &clause, p.errorExpected(p.pos, p.tok, "SET")
1880		}
1881		clause.DoUpdateSet, _, _ = p.scan()
1882	
1883		// Parse list of assignments.
1884		for {
1885			assignment, err := p.parseAssignment()
1886			if err != nil {
1887				return &clause, err
1888			}
1889			clause.Assignments = append(clause.Assignments, assignment)
1890	
1891			if p.peek() != COMMA {
1892				break
1893			}
1894			p.scan()
1895		}
1896	
1897		// Parse WHERE after DO UPDATE SET.
1898		if p.peek() == WHERE {
1899			clause.UpdateWhere, _, _ = p.scan()
1900			if clause.UpdateWhereExpr, err = p.ParseExpr(); err != nil {
1901				return &clause, err
1902			}
1903		}
1904	
1905		return &clause, nil
1906	}
