1908	func (p *Parser) parseReturningClause() (_ *ReturningClause, err error) {
1909		assert(p.peek() == RETURNING)
1910	
1911		var clause ReturningClause
1912	
1913		clause.Returning, _, _ = p.scan()
1914		// Parse result columns.
1915		for {
1916			col, err := p.parseResultColumn()
1917			if err != nil {
1918				return &clause, err
1919			}
1920			clause.Columns = append(clause.Columns, col)
1921	
1922			if p.peek() != COMMA {
1923				break
1924			}
1925			p.scan()
1926		}
1927	
1928		return &clause, nil
1929	}
