2376	func (p *Parser) parseResultColumn() (_ *ResultColumn, err error) {
2377		var col ResultColumn
2378	
2379		// An initial "*" returns all columns.
2380		if p.peek() == STAR {
2381			col.Star, _, _ = p.scan()
2382			return &col, nil
2383		}
2384	
2385		// Next can be either "EXPR [[AS] column-alias]" or "IDENT DOT STAR".
2386		// We need read the next element as an expression and then determine what next.
2387		if col.Expr, err = p.ParseExpr(); err != nil {
2388			return &col, err
2389		}
2390	
2391		// If we have a qualified ref w/ a star, don't allow an alias.
2392		if ref, ok := col.Expr.(*QualifiedRef); ok && ref.Star.IsValid() {
2393			return &col, nil
2394		}
2395	
2396		// If "AS" is next, the alias must follow.
2397		// Otherwise it can optionally be an identifier or string alias.
2398		if p.peek() == AS {
2399			col.As, _, _ = p.scan()
2400			if !isAliasToken(p.peek()) {
2401				return &col, p.errorExpected(p.pos, p.tok, "column alias")
2402			}
2403			col.Alias, _ = p.parseAlias("column alias")
2404		} else if isAliasToken(p.peek()) {
2405			col.Alias, _ = p.parseAlias("column alias")
2406		}
2407	
2408		return &col, nil
2409	}
2410	
2411	func (p *Parser) parseSource() (source Source, err error) {
2412		source, err = p.parseUnarySource()
2413		if err != nil {
2414			return source, err
2415		}
2416	
2417		for {
2418			// Exit immediately if not part of a join operator.
2419			switch p.peek() {
2420			case COMMA, NATURAL, LEFT, RIGHT, FULL, INNER, CROSS, JOIN:
2421			default:
2422				return source, nil
2423			}
2424	
2425			// Parse join operator.
2426			operator, err := p.parseJoinOperator()
2427			if err != nil {
2428				return source, err
2429			}
2430			y, err := p.parseUnarySource()
2431			if err != nil {
2432				return source, err
2433			}
2434			constraint, err := p.parseJoinConstraint()
2435			if err != nil {
2436				return source, err
2437			}
2438	
2439			source = &JoinClause{X: source, Operator: operator, Y: y, Constraint: constraint}
2440		}
2441	}
2442	
2443	// parseUnarySource parses a qualified table name, table function name, or subquery but not a JOIN.
2444	func (p *Parser) parseUnarySource() (source Source, err error) {
2445		if err := p.incDepth(p.pos); err != nil {
2446			return nil, err
2447		}
2448		defer p.decDepth()
2449	
2450		switch p.peek() {
2451		case LP:
2452			return p.parseParenSource()
2453		case IDENT, QIDENT, BIDENT:
2454			return p.parseQualifiedTable(true, true, true)
2455		case VALUES:
2456			return p.parseSelectStatement(false, nil)
2457		default:
2458			return nil, p.errorExpected(p.pos, p.tok, "table name or left paren")
2459		}
2460	}
2461	
2462	func (p *Parser) parseJoinOperator() (*JoinOperator, error) {
2463		var op JoinOperator
2464	
2465		// Handle single comma join.
2466		if p.peek() == COMMA {
2467			op.Comma, _, _ = p.scan()
2468			return &op, nil
2469		}
2470	
2471		if p.peek() == NATURAL {
2472			op.Natural, _, _ = p.scan()
2473		}
2474	
2475		// Parse "LEFT", "RIGHT" or "FULL" (each optionally followed by "OUTER"),
2476		// "INNER", or "CROSS".
2477		switch p.peek() {
2478		case LEFT, RIGHT, FULL:
2479			switch pos, tok, _ := p.scan(); tok {
2480			case LEFT:
2481				op.Left = pos
2482			case RIGHT:
2483				op.Right = pos
2484			default:
2485				op.Full = pos
2486			}
2487			if p.peek() == OUTER {
2488				op.Outer, _, _ = p.scan()
2489			}
2490		case INNER:
2491			op.Inner, _, _ = p.scan()
2492		case CROSS:
2493			op.Cross, _, _ = p.scan()
2494		}
2495	
2496		// Parse final JOIN.
2497		if p.peek() != JOIN {
2498			return &op, p.errorExpected(p.pos, p.tok, "JOIN")
2499		}
2500		op.Join, _, _ = p.scan()
2501	
2502		return &op, nil
2503	}
2504	
2505	func (p *Parser) parseJoinConstraint() (JoinConstraint, error) {
2506		switch p.peek() {
2507		case ON:
2508			return p.parseOnConstraint()
2509		case USING:
2510			return p.parseUsingConstraint()
2511		default:
2512			return nil, nil
2513		}
2514	}
