cd /tmp/sqlitecheck && cat > main.go <<'EOF'
package main

import (
	"database/sql"
	"fmt"

	_ "modernc.org/sqlite"
)

func run(db *sql.DB, s string) {
	rows, err := db.Query(s)
	if err != nil {
		fmt.Printf("ERR  %-55s %v\n", s, err)
		return
	}
	cols, _ := rows.Columns()
	n := 0
	for rows.Next() {
		n++
	}
	rows.Close()
	fmt.Printf("OK   %-55s cols=%v rows=%d\n", s, cols, n)
}

func main() {
	db, _ := sql.Open("sqlite", ":memory:")
	db.Exec(`CREATE TABLE u (id INTEGER PRIMARY KEY, x INT, key INT)`)
	db.Exec(`INSERT INTO u VALUES (1,10,100),(2,20,200)`)
	// fallback keyword KEY in expression/alias/limit positions
	run(db, `SELECT key FROM u`)
	run(db, `SELECT 1 AS key`)
	run(db, `SELECT 1 key`)
	run(db, `SELECT * FROM u LIMIT key`)
	run(db, `SELECT * FROM u LIMIT 1 OFFSET key`)
	run(db, `SELECT * FROM u ORDER BY key LIMIT 1`)
	// reserved RETURNING in the same positions
	run(db, `SELECT 1 AS returning`)
	run(db, `SELECT 1 returning`)
	run(db, `SELECT * FROM u LIMIT returning`)
	// table name / alias positions
	run(db, `SELECT * FROM u key`)
	run(db, `SELECT * FROM u AS key`)
	run(db, `SELECT * FROM key`)
	// CTE name
	run(db, `WITH key AS (SELECT 1) SELECT * FROM key`)
	// SET target
	run(db, `UPDATE u SET key = 1`)
	// INSERT column list
	run(db, `INSERT INTO u (key) VALUES (1)`)
	// what about a fallback keyword immediately before a real clause keyword:
	run(db, `SELECT * FROM u WHERE key > 0 ORDER BY id LIMIT 1`)
	// two-word: LIMIT key then another clause-ish token
	run(db, `SELECT * FROM u LIMIT key, 1`)
}
EOF
