func (p *Parser) parseColumnDefinitions() (_ []*ColumnDefinition, err error) {
	var columns []*ColumnDefinition
	for {
		if tok := p.peek(); isIdentToken(tok) || isBareToken(tok) {
			col, err := p.parseColumnDefinition()
			columns = append(columns, col)
			if err != nil {
				return columns, err
			}
			// Column definitions must be comma separated. Without a comma the
			// list is complete and the caller verifies what follows. After a
			// comma another column or a table constraint is required.
			if p.peek() != COMMA {
				return columns, nil
			}
			p.scan()
			if p.peek() == RP {
				return columns, p.errorExpected(p.pos, p.tok, "column name or CONSTRAINT")
			}
		} else if tok == RP || isConstraintStartToken(tok, true) {
			return columns, nil
		} else {
			return columns, p.errorExpected(p.pos, p.tok, "column name, CONSTRAINT, or right paren")
		}
	}
}

