// Ensure the parser returns an error on pathologically nested input instead
// of overflowing the stack.
func TestParser_DepthLimit(t *testing.T) {
	t.Run("NestedExprOK", func(t *testing.T) {
		AssertParseStatements(t, `SELECT `+strings.Repeat("(", 900)+`1`+strings.Repeat(")", 900), 1)
	})
	t.Run("NestedExpr", func(t *testing.T) {
		s := `SELECT ` + strings.Repeat("(", 2000) + `1` + strings.Repeat(")", 2000)
		AssertParseStatementsError(t, s, `parse tree is too deep (maximum depth 1000)`)
	})
	t.Run("NestedUnary", func(t *testing.T) {
		s := `SELECT ` + strings.Repeat("NOT ", 2000) + `1`
		AssertParseStatementsError(t, s, `parse tree is too deep (maximum depth 1000)`)
	})
	t.Run("NestedSourceOK", func(t *testing.T) {
		AssertParseStatements(t, `SELECT * FROM `+strings.Repeat("(", 500)+`tbl`+strings.Repeat(")", 500), 1)
	})
	t.Run("NestedSource", func(t *testing.T) {
		s := `SELECT * FROM ` + strings.Repeat("(", 2000) + `tbl` + strings.Repeat(")", 2000)
		AssertParseStatementsError(t, s, `parse tree is too deep (maximum depth 1000)`)
	})

	// The depth counter must reset between statements.
	t.Run("MultipleStatements", func(t *testing.T) {
		stmt := `SELECT ` + strings.Repeat("(", 800) + `1` + strings.Repeat(")", 800) + `; `
		AssertParseStatements(t, strings.Repeat(stmt, 3), 3)
	})
}

// Ensure schema-qualified table-valued functions are accepted where sqlite3
// accepts them: in FROM and as the right hand side of IN. A schema-qualified
// ordinary function call is a syntax error in sqlite3 and is rejected here too.
func TestParser_SchemaQualifiedFunctions(t *testing.T) {
	stmt := ParseStatementOrFail(t, `SELECT 1 FROM main.json_each('[1]') AS j WHERE 2 IN main.tf(3)`).(*sql.SelectStatement)
	if fn, ok := stmt.Source.(*sql.QualifiedTableFunctionName); !ok {
		t.Fatalf("source: expected *sql.QualifiedTableFunctionName, got %T", stmt.Source)
	} else if diff := deepEqual(fn, &sql.QualifiedTableFunctionName{
		Schema: &sql.Ident{Name: "main", NamePos: pos(14)},
		Dot:    pos(18),
		Name:   &sql.Ident{Name: "json_each", NamePos: pos(19)},
		Lparen: pos(28),
		Args:   []sql.Expr{&sql.StringLit{Value: "[1]", ValuePos: pos(29)}},
		Rparen: pos(34),
		As:     pos(36),
		Alias:  &sql.Ident{Name: "j", NamePos: pos(39)},
	}); diff != "" {
		t.Fatal(diff)
	}
	if in, ok := stmt.WhereExpr.(*sql.BinaryExpr); !ok || in.Op != sql.IN {
		t.Fatalf("where: expected IN expression, got %s", stmt.WhereExpr.String())
	} else if diff := deepEqual(in.Y, &sql.Call{
		Schema: &sql.Ident{Name: "main", NamePos: pos(52)},
		Dot:    pos(56),
		Name:   &sql.Ident{Name: "tf", NamePos: pos(57)},
		Lparen: pos(59),
		Args:   []sql.Expr{&sql.NumberLit{Value: "3", ValuePos: pos(60)}},
		Rparen: pos(61),
	}); diff != "" {
		t.Fatal(diff)
	}
	if got, want := stmt.String(), `SELECT 1 FROM "main"."json_each"('[1]') AS "j" WHERE 2 IN "main".tf(3)`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}

	AssertParseStatementError(t, `SELECT main.func(1)`, `1:17: expected semicolon or EOF, found '('`)

	// Plain column references are unaffected.
	AssertParseExpr(t, `tbl.col`, &sql.QualifiedRef{
		Table:  &sql.Ident{Name: "tbl", NamePos: pos(0)},
		Dot:    pos(3),
		Column: &sql.Ident{Name: "col", NamePos: pos(4)},
	})
}

// Ensure schema-qualified object names are accepted wherever SQLite allows them.
func TestParser_SchemaQualifiedNames(t *testing.T) {
	for _, tt := range []struct {
		s      string
		schema func(sql.Statement) (*sql.Ident, *sql.Ident)
	}{
		{`CREATE VIEW main.v AS SELECT 1`, func(st sql.Statement) (*sql.Ident, *sql.Ident) {
			v := st.(*sql.CreateViewStatement)
			return v.Schema, v.Name
		}},
		{`CREATE TRIGGER main.trg BEFORE DELETE ON t BEGIN SELECT 1; END`, func(st sql.Statement) (*sql.Ident, *sql.Ident) {
			v := st.(*sql.CreateTriggerStatement)
			return v.Schema, v.Name
		}},
		{`DROP TRIGGER IF EXISTS main.trg`, func(st sql.Statement) (*sql.Ident, *sql.Ident) {
			v := st.(*sql.DropTriggerStatement)
			return v.Schema, v.Name
		}},
		{`ANALYZE main.t`, func(st sql.Statement) (*sql.Ident, *sql.Ident) {
			v := st.(*sql.AnalyzeStatement)
			return v.Schema, v.Name
		}},
		{`DROP VIEW IF EXISTS main.v`, func(st sql.Statement) (*sql.Ident, *sql.Ident) {
			v := st.(*sql.DropViewStatement)
			return v.Schema, v.Name
		}},
		{`CREATE TRIGGER trg AFTER INSERT ON main.t BEGIN SELECT 1; END`, func(st sql.Statement) (*sql.Ident, *sql.Ident) {
			v := st.(*sql.CreateTriggerStatement)
			return v.TableSchema, v.Table
		}},
	} {
		stmt, err := sql.NewParser(strings.NewReader(tt.s)).ParseStatement()
		if err != nil {
			t.Errorf("%s: %v", tt.s, err)
			continue
		}
		schema, name := tt.schema(stmt)
		if schema == nil || schema.Name != "main" {
			t.Errorf("%s: schema=%v, want main", tt.s, schema)
		} else if name == nil || name.Name == "main" {
			t.Errorf("%s: name=%v", tt.s, name)
		}
		// Round trip.
		if stmt2, err := sql.NewParser(strings.NewReader(stmt.String())).ParseStatement(); err != nil {
			t.Errorf("%s: cannot re-parse %q: %v", tt.s, stmt.String(), err)
		} else if stmt2.String() != stmt.String() {
			t.Errorf("%s: unstable: %q != %q", tt.s, stmt.String(), stmt2.String())
		}
	}
}

// Ensure virtual table module arguments accept the forms FTS5 and other
// modules use: a column with a type-like word (UNINDEXED), a quoted or string
// name, an option assigned a function-call value, and no arguments at all.
func TestParser_ModuleArguments(t *testing.T) {
	// A real FTS5 declaration that sqlite3 executes, as does its String().
	stmt := ParseStatementOrFail(t, `CREATE VIRTUAL TABLE ft USING fts5(a UNINDEXED, 'b c', tokenize=porter, prefix='2 3')`).(*sql.CreateVirtualTableStatement)
	if len(stmt.Arguments) != 4 {
		t.Fatalf("expected 4 arguments, got %d", len(stmt.Arguments))
	}
	if got := stmt.Arguments[0].Type.Name.Name; got != "UNINDEXED" {
		t.Errorf("arg 0 type=%q, want UNINDEXED", got)
	}
	if got := stmt.Arguments[1].Name.Name; got != "b c" {
		t.Errorf("arg 1 name=%q, want %q", got, "b c")
	}
	if _, ok := stmt.Arguments[2].Literal.(*sql.Ident); !ok {
		t.Errorf("arg 2 value=%T, want *sql.Ident", stmt.Arguments[2].Literal)
	}
	if got, want := stmt.String(), `CREATE VIRTUAL TABLE "ft" USING "fts5" (a UNINDEXED,"b c",tokenize="porter",prefix='2 3')`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
	if _, err := sql.NewParser(strings.NewReader(stmt.String())).ParseStatement(); err != nil {
		t.Fatalf("cannot re-parse %q: %v", stmt.String(), err)
	}
	// An empty argument list (dbstat takes none).
	stmt = ParseStatementOrFail(t, `CREATE VIRTUAL TABLE s USING dbstat()`).(*sql.CreateVirtualTableStatement)
	if len(stmt.Arguments) != 0 || stmt.String() != `CREATE VIRTUAL TABLE "s" USING "dbstat" ()` {
		t.Fatalf("unexpected: %s", stmt.String())
	}
	// R*Tree auxiliary columns are introduced by a "+" prefix.
	stmt = ParseStatementOrFail(t, `CREATE VIRTUAL TABLE r USING rtree(id, minX, maxX, +label TEXT, +other)`).(*sql.CreateVirtualTableStatement)
	if len(stmt.Arguments) != 5 || !stmt.Arguments[3].Plus.IsValid() || stmt.Arguments[3].Name.Name != "label" || stmt.Arguments[3].Type.Name.Name != "TEXT" || !stmt.Arguments[4].Plus.IsValid() {
		t.Fatalf("unexpected rtree arguments: %s", stmt.String())
	}
	if got, want := stmt.String(), `CREATE VIRTUAL TABLE "r" USING "rtree" (id,minX,maxX,+label TEXT,+other)`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
	// An option whose value is a call parses as a Call.
	stmt = ParseStatementOrFail(t, `CREATE VIRTUAL TABLE vtbl USING mdl(c=d(e))`).(*sql.CreateVirtualTableStatement)
	if _, ok := stmt.Arguments[0].Literal.(*sql.Call); !ok {
		t.Errorf("value=%T, want *sql.Call", stmt.Arguments[0].Literal)
	}
}

// Ensure a string literal is accepted as a column or table alias, as sqlite3
// allows (as ::= AS nm | ids, where ids includes STRING).
func TestParser_StringAlias(t *testing.T) {
	stmt := ParseStatementOrFail(t, `SELECT x 'lbl', y AS 'lbl2' FROM t 'a' JOIN json_each('[1]') 'j'`).(*sql.SelectStatement)
	if diff := deepEqual(stmt.Columns[0].Alias, &sql.Ident{Name: "lbl", NamePos: pos(9), Quoted: true}); diff != "" {
		t.Fatal(diff)
	}
	if diff := deepEqual(stmt.Columns[1].Alias, &sql.Ident{Name: "lbl2", NamePos: pos(21), Quoted: true}); diff != "" {
		t.Fatal(diff)
	}
	join := stmt.Source.(*sql.JoinClause)
	if alias := join.X.(*sql.QualifiedTableName).Alias; alias == nil || alias.Name != "a" {
		t.Fatalf("table alias=%v, want a", alias)
	}
	if alias := join.Y.(*sql.QualifiedTableFunctionName).Alias; alias == nil || alias.Name != "j" {
		t.Fatalf("table function alias=%v, want j", alias)
	}
	if got, want := stmt.String(), `SELECT "x" AS "lbl", "y" AS "lbl2" FROM "t" AS "a" JOIN "json_each"('[1]') AS "j"`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
}

