		t.Fatalf("String()=%s, want %s", got, want)
	}
	AssertParseExpr(t, `ü`, &sql.Ident{Name: "ü", NamePos: pos(0)})
}

// Ensure a CONSTRAINT name with no constraint after it is accepted (SQLite
// ignores it) rather than crashing the parser, and that a name followed by
// something that is not a constraint is a parse error.
func TestParser_EmptyConstraint(t *testing.T) {
	stmt := ParseStatementOrFail(t, `CREATE TABLE tbl (col1 INTEGER CONSTRAINT c, col2 CONSTRAINT d NOT NULL, CONSTRAINT e)`).(*sql.CreateTableStatement)
	if diff := deepEqual(stmt.Columns[0].Constraints, []sql.Constraint{
		&sql.EmptyConstraint{Constraint: pos(31), Name: &sql.Ident{Name: "c", NamePos: pos(42)}},
	}); diff != "" {
		t.Fatal(diff)
	}
	if diff := deepEqual(stmt.Columns[1].Constraints, []sql.Constraint{
		&sql.NotNullConstraint{Constraint: pos(50), Name: &sql.Ident{Name: "d", NamePos: pos(61)}, Not: pos(63), Null: pos(67)},
	}); diff != "" {
		t.Fatal(diff)
	}
	if diff := deepEqual(stmt.Constraints, []sql.Constraint{
		&sql.EmptyConstraint{Constraint: pos(73), Name: &sql.Ident{Name: "e", NamePos: pos(84)}},
	}); diff != "" {
		t.Fatal(diff)
	}
	if got, want := stmt.String(), `CREATE TABLE "tbl" ("col1" INTEGER CONSTRAINT "c", "col2" CONSTRAINT "d" NOT NULL, CONSTRAINT "e")`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
	AssertParseStatementError(t, `CREATE TABLE tbl (col1 INTEGER CONSTRAINT c FOO)`, `1:45: expected PRIMARY KEY, NOT NULL, UNIQUE, CHECK, DEFAULT, COLLATE, REFERENCES, or GENERATED, found FOO`)
	AssertParseStatementError(t, `CREATE TABLE tbl (col1, CONSTRAINT c FOO)`, `1:38: expected PRIMARY KEY, UNIQUE, CHECK, or FOREIGN KEY, found FOO`)
}

// Ensure a DEFAULT value may be a bare identifier, which SQLite stores as a
// string: `DEFAULT abc` is the same as `DEFAULT 'abc'`.
func TestParser_DefaultIdent(t *testing.T) {
	stmt := ParseStatementOrFail(t, `CREATE TABLE tbl (col1 TEXT DEFAULT abc, col2 TEXT DEFAULT key)`).(*sql.CreateTableStatement)
	if diff := deepEqual(stmt.Columns[0].Constraints[0], &sql.DefaultConstraint{
		Default: pos(28),
		Expr:    &sql.Ident{NamePos: pos(36), Name: "abc"},
	}); diff != "" {
		t.Fatal(diff)
	}
	if got, want := stmt.String(), `CREATE TABLE "tbl" ("col1" TEXT DEFAULT abc, "col2" TEXT DEFAULT key)`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
	AssertParseStatementError(t, `CREATE TABLE tbl (col1 TEXT DEFAULT)`, `1:36: expected literal value, identifier or left paren, found ')'`)
}

// Ensure type names may be quoted identifiers, string literals or fallback
// keywords, as sqlite3 allows (typename ::= ids | typename ids).
func TestParser_TypeNames(t *testing.T) {
	for _, tt := range []struct{ s, typ string }{
		{`CREATE TABLE tbl (col1 "my type")`, "my type"},
		{`CREATE TABLE tbl (col1 'my type')`, "my type"},
		{"CREATE TABLE tbl (col1 `bt type`(10))", "bt type"},
		{`CREATE TABLE tbl (col1 key)`, "key"},
		{`CREATE TABLE tbl (col1 INTEGER key)`, "INTEGER key"},
		{`CREATE TABLE tbl (col1 UNSIGNED BIG INT NOT NULL)`, "UNSIGNED BIG INT"},
	} {
		stmt := ParseStatementOrFail(t, tt.s).(*sql.CreateTableStatement)
		if len(stmt.Columns) != 1 {
			t.Errorf("%s: expected 1 column, got %d", tt.s, len(stmt.Columns))
		} else if got := stmt.Columns[0].Type.Name.Name; got != tt.typ {
			t.Errorf("%s: type=%q, want %q", tt.s, got, tt.typ)
		}
		if _, err := sql.NewParser(strings.NewReader(stmt.String())).ParseStatement(); err != nil {
			t.Errorf("%s: cannot re-parse %q: %v", tt.s, stmt.String(), err)
		}
	}
	// GENERATED starts a constraint and is never part of a type name.
	stmt := ParseStatementOrFail(t, `CREATE TABLE tbl (col1 INTEGER GENERATED ALWAYS AS (1), col2)`).(*sql.CreateTableStatement)
	if got := stmt.Columns[0].Type.Name.Name; got != "INTEGER" {
		t.Errorf("type=%q, want INTEGER", got)
	} else if len(stmt.Columns[0].Constraints) != 1 {
		t.Errorf("expected generated constraint, got %v", stmt.Columns[0].Constraints)
	}
	// The type of a CAST may be empty, as sqlite3 allows.
	AssertParseExpr(t, `CAST(1 AS)`, &sql.CastExpr{
		Cast:   pos(0),
		Lparen: pos(4),
		X:      &sql.NumberLit{Value: "1", ValuePos: pos(5)},
		As:     pos(7),
		Rparen: pos(9),
	})
	if e, err := sql.NewParser(strings.NewReader(`CAST(1 AS "weird type")`)).ParseExpr(); err != nil {
		t.Fatal(err)
	} else if got := e.(*sql.CastExpr).Type.Name.Name; got != "weird type" {
		t.Errorf("CAST type=%q, want %q", got, "weird type")
	}
}

// Ensure rowid and fallback keywords are accepted as column names after a dot
// and in INSERT column lists, as sqlite3 does.
func TestParser_RowidAndKeywordColumns(t *testing.T) {
	AssertParseExpr(t, `t.rowid`, &sql.QualifiedRef{
		Table:  &sql.Ident{Name: "t", NamePos: pos(0)},
		Dot:    pos(1),
		Column: &sql.Ident{Name: "rowid", NamePos: pos(2)},
	})
	AssertParseExpr(t, `main.t.key`, &sql.QualifiedRef{
		Schema:    &sql.Ident{Name: "main", NamePos: pos(0)},
		SchemaPos: pos(4),
		Table:     &sql.Ident{Name: "t", NamePos: pos(5)},
		Dot:       pos(6),
		Column:    &sql.Ident{Name: "key", NamePos: pos(7)},
	})
	for _, s := range []string{
		`INSERT INTO t (rowid, x) VALUES (1, 2)`,
		`UPDATE t SET rowid = 1`,
		`SELECT t.rowid, t.key FROM t`,
	} {
		stmt, err := sql.NewParser(strings.NewReader(s)).ParseStatement()
		if err != nil {
			t.Errorf("%s: %v", s, err)
		} else if _, err := sql.NewParser(strings.NewReader(stmt.String())).ParseStatement(); err != nil {
			t.Errorf("%s: cannot re-parse %q: %v", s, stmt.String(), err)
		}
	}
}

// Ensure names that are not SQLite keywords can be used as identifiers.
func TestParser_NonKeywordIdents(t *testing.T) {
	for _, s := range []string{
		`SELECT vector, span, truth FROM tbl`,
		`SELECT function, register, variable FROM tbl`,
		`CREATE TABLE tbl (vector BLOB, strict INTEGER, stored TEXT)`,
		`SELECT * FROM vector WHERE span > 1`,
		`SELECT [a b], [c] FROM [my table]`,
	} {
		stmt, err := sql.NewParser(strings.NewReader(s)).ParseStatement()
		if err != nil {
			t.Errorf("%s: %v", s, err)
		} else if _, err := sql.NewParser(strings.NewReader(stmt.String())).ParseStatement(); err != nil {
			t.Errorf("%s: cannot re-parse %q: %v", s, stmt.String(), err)
		}
	}
}

// Ensure operators that are not valid binary operators are rejected rather
// than accepted as expressions that cannot be re-serialized.
func TestParser_InvalidBinaryOp(t *testing.T) {
	AssertParseStatementError(t, `SELECT 1 ~ 2`, `1:10: expected semicolon or EOF, found '~'`)
	AssertParseStatementError(t, `SELECT 1 ESCAPE 2`, `1:10: expected semicolon or EOF, found 'ESCAPE'`)
	AssertParseStatementError(t, `SELECT * FROM tbl WHERE x = 'y' ESCAPE '@'`, `1:33: expected semicolon or EOF, found 'ESCAPE'`)
}

func TestError_Error(t *testing.T) {
	err := &sql.Error{Msg: "test"}
	if got, want := err.Error(), `test`; got != want {
		t.Fatalf("Error()=%s, want %s", got, want)
	}
}

// ParseStatementOrFail parses a statement from s. Fail on error.
func ParseStatementOrFail(tb testing.TB, s string) sql.Statement {
	tb.Helper()
	stmt, err := sql.NewParser(strings.NewReader(s)).ParseStatement()
	if err != nil {
		tb.Fatal(err)
	}
	return stmt
}

// AssertParseStatement asserts the value of the first parse of s.
func AssertParseStatement(tb testing.TB, s string, want sql.Statement) {
	tb.Helper()
	stmt, err := sql.NewParser(strings.NewReader(s)).ParseStatement()
	if err != nil {
		tb.Fatal(err)
	} else if diff := deep.Equal(stmt, want); diff != nil {
		tb.Fatalf("mismatch:\n%s", strings.Join(diff, "\n"))
	}
}

// AssertParseStatementError asserts s parses to a given error string.
func AssertParseStatementError(tb testing.TB, s string, want string) {
	tb.Helper()
	_, err := sql.NewParser(strings.NewReader(s)).ParseStatement()
	if err == nil || err.Error() != want {
		tb.Fatalf("ParseStatement()=%q, want %q", err, want)
	}
}

// AssertParseStatements asserts the count of statements parsed from s.
func AssertParseStatements(tb testing.TB, s string, wantCount int) {
	tb.Helper()
	stmts, err := sql.NewParser(strings.NewReader(s)).ParseStatements()
	if err != nil {
		tb.Fatal(err)
	} else if len(stmts) != wantCount {
		tb.Fatalf("ParseStatements()=%d statements, want %d", len(stmts), wantCount)
	}
}

// AssertParseStatementsError asserts s parses to a given error substring.
func AssertParseStatementsError(tb testing.TB, s string, wantSubstring string) {
	tb.Helper()
	_, err := sql.NewParser(strings.NewReader(s)).ParseStatements()
	if err == nil {
		tb.Fatal("ParseStatements() expected error, got nil")
	}
	if !strings.Contains(err.Error(), wantSubstring) {
		tb.Fatalf("ParseStatements() error=%q, want error containing %q", err, wantSubstring)
	}
}

// ParseExprOrFail parses a expression from s. Fail on error.
func ParseExprOrFail(tb testing.TB, s string) sql.Expr {
	tb.Helper()
	stmt, err := sql.NewParser(strings.NewReader(s)).ParseExpr()
	if err != nil {
		tb.Fatal(err)
	}
	return stmt
}

// AssertParseExpr asserts the value of the first parse of s.
func AssertParseExpr(tb testing.TB, s string, want sql.Expr) {
	tb.Helper()
	stmt, err := sql.NewParser(strings.NewReader(s)).ParseExpr()
	if err != nil {
		tb.Fatal(err)
