			Insert: pos(0),
			Into:   pos(7),
			Table:  &sql.Ident{NamePos: pos(12), Name: "tbl"},
			ColumnsLparen: pos(15),
			Columns:       []*sql.Ident{{NamePos: pos(16), Name: "x"}},
			ColumnsRparen: pos(17),
			Values:        pos(19),
			ValueLists: []*sql.ExprList{{
