		// and must be accepted as names.
		AssertParseStatement(t, `PRAGMA foreign_keys = ON`, &sql.PragmaStatement{
			Pragma: pos(0),
			Expr: &sql.BinaryExpr{
				X:     &sql.Ident{Name: "foreign_keys", NamePos: pos(7)},
