func TestParser_ParseStatements(t *testing.T) {
	t.Run("EmptyInput", func(t *testing.T) {
		AssertParseStatements(t, ``, 0)
	})

	t.Run("SingleStatement", func(t *testing.T) {
		AssertParseStatements(t, `SELECT * FROM foo`, 1)
	})

	t.Run("MultipleStatementsWithSemicolons", func(t *testing.T) {
		AssertParseStatements(t, `SELECT * FROM foo; SELECT * FROM bar;`, 2)
	})

	t.Run("ThreeStatementsWithSemicolons", func(t *testing.T) {
		AssertParseStatements(t, `BEGIN; SELECT 1; COMMIT;`, 3)
	})

	t.Run("MixedStatementTypes", func(t *testing.T) {
		input := `
			CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT);
			INSERT INTO users (id, name) VALUES (1, 'Alice');
			SELECT * FROM users;
			UPDATE users SET name = 'Bob' WHERE id = 1;
			DELETE FROM users WHERE id = 1;
		`
		AssertParseStatements(t, input, 5)
	})

	t.Run("StatementWithoutTrailingSemicolon", func(t *testing.T) {
		AssertParseStatements(t, `SELECT * FROM foo`, 1)
	})

	t.Run("StatementWithLeadingWhitespace", func(t *testing.T) {
		AssertParseStatements(t, `  

			SELECT * FROM foo;
		`, 1)
	})

	t.Run("ExplainStatements", func(t *testing.T) {
		AssertParseStatements(t, `EXPLAIN SELECT * FROM foo; EXPLAIN QUERY PLAN SELECT * FROM bar;`, 2)
	})

	t.Run("PragmaStatements", func(t *testing.T) {
		AssertParseStatements(t, `PRAGMA journal_mode; PRAGMA foreign_keys = 'ON';`, 2)
	})

	t.Run("TransactionStatements", func(t *testing.T) {
		AssertParseStatements(t, `BEGIN TRANSACTION; ROLLBACK; BEGIN; COMMIT;`, 4)
	})

	t.Run("MissingSemicolonBetweenStatements", func(t *testing.T) {
		AssertParseStatementsError(t, `SELECT * FROM foo SELECT * FROM bar`, "semicolon or EOF")
	})

	t.Run("InvalidStatement", func(t *testing.T) {
		_, err := sql.NewParser(strings.NewReader(`INVALID STATEMENT;`)).ParseStatements()
		if err == nil {
			t.Fatal("ParseStatements() expected error, got nil")
		}
	})

	t.Run("EmptySemicolons", func(t *testing.T) {
		// Empty statements are skipped, as sqlite3 does.
		AssertParseStatements(t, `;;`, 0)
	})

	t.Run("CreateIndexStatements", func(t *testing.T) {
		AssertParseStatements(t, `CREATE INDEX idx_foo ON foo(bar); CREATE UNIQUE INDEX idx_baz ON baz(qux);`, 2)
	})

	t.Run("DropStatements", func(t *testing.T) {
		AssertParseStatements(t, `DROP TABLE foo; DROP INDEX idx; DROP VIEW v;`, 3)
	})

	t.Run("MixedWhitespaceAndComments", func(t *testing.T) {
		input := `
			SELECT * FROM foo;

			-- This is a comment
			SELECT * FROM bar;
		`
		AssertParseStatements(t, input, 2)
	})
}

func TestParser_ParseExpr(t *testing.T) {
	t.Run("Ident", func(t *testing.T) {
		AssertParseExpr(t, `fooBAR_123'`, &sql.Ident{NamePos: pos(0), Name: `fooBAR_123`})
	})
	t.Run("StringLit", func(t *testing.T) {
		AssertParseExpr(t, `'foo bar'`, &sql.StringLit{ValuePos: pos(0), Value: `foo bar`})
	})
	t.Run("BlobLit", func(t *testing.T) {
		AssertParseExpr(t, `x'0123'`, &sql.BlobLit{ValuePos: pos(0), Value: `0123`})
	})
	t.Run("Integer", func(t *testing.T) {
		AssertParseExpr(t, `123`, &sql.NumberLit{ValuePos: pos(0), Value: `123`})
	})
	t.Run("Float", func(t *testing.T) {
		AssertParseExpr(t, `123.456`, &sql.NumberLit{ValuePos: pos(0), Value: `123.456`})
	})
	t.Run("Null", func(t *testing.T) {
		AssertParseExpr(t, `NULL`, &sql.NullLit{Pos: pos(0)})
	})
	t.Run("Bool", func(t *testing.T) {
		AssertParseExpr(t, `true`, &sql.BoolLit{ValuePos: pos(0), Value: true})
		AssertParseExpr(t, `false`, &sql.BoolLit{ValuePos: pos(0), Value: false})
	})
	t.Run("Bind", func(t *testing.T) {
		AssertParseExpr(t, `$bar`, &sql.BindExpr{NamePos: pos(0), Name: "$bar"})
	})
	t.Run("UnaryExpr", func(t *testing.T) {
		AssertParseExpr(t, `-123`, &sql.UnaryExpr{OpPos: pos(0), Op: sql.MINUS, X: &sql.NumberLit{ValuePos: pos(1), Value: `123`}})
		AssertParseExpr(t, `NOT foo`, &sql.UnaryExpr{OpPos: pos(0), Op: sql.NOT, X: &sql.Ident{NamePos: pos(4), Name: "foo"}})
		// Unary NOT binds looser than comparison operators but tighter than AND/OR.
		AssertParseExpr(t, `NOT 1 = 2`, &sql.UnaryExpr{OpPos: pos(0), Op: sql.NOT, X: &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(4), Value: "1"},
			OpPos: pos(6), Op: sql.EQ,
			Y: &sql.NumberLit{ValuePos: pos(8), Value: "2"},
		}})
		AssertParseExpr(t, `NOT a LIKE b`, &sql.UnaryExpr{OpPos: pos(0), Op: sql.NOT, X: &sql.BinaryExpr{
			X:     &sql.Ident{NamePos: pos(4), Name: "a"},
			OpPos: pos(6), Op: sql.LIKE,
			Y: &sql.Ident{NamePos: pos(11), Name: "b"},
		}})
		AssertParseExpr(t, `NOT 1 = 2 AND 3`, &sql.BinaryExpr{
			X: &sql.UnaryExpr{OpPos: pos(0), Op: sql.NOT, X: &sql.BinaryExpr{
				X:     &sql.NumberLit{ValuePos: pos(4), Value: "1"},
				OpPos: pos(6), Op: sql.EQ,
				Y: &sql.NumberLit{ValuePos: pos(8), Value: "2"},
			}},
			OpPos: pos(10), Op: sql.AND,
			Y: &sql.NumberLit{ValuePos: pos(14), Value: "3"},
		})
		AssertParseExpr(t, `NOT NOT 1`, &sql.UnaryExpr{OpPos: pos(0), Op: sql.NOT, X: &sql.UnaryExpr{OpPos: pos(4), Op: sql.NOT, X: &sql.NumberLit{ValuePos: pos(8), Value: "1"}}})
		AssertParseExpr(t, `~1`, &sql.UnaryExpr{OpPos: pos(0), Op: sql.BITNOT, X: &sql.NumberLit{ValuePos: pos(1), Value: "1"}})
		AssertParseExprError(t, `-`, `1:1: expected expression, found 'EOF'`)
	})
	t.Run("QualifiedRef", func(t *testing.T) {
		AssertParseExpr(t, `tbl.col`, &sql.QualifiedRef{
			Table:  &sql.Ident{NamePos: pos(0), Name: "tbl"},
			Dot:    pos(3),
			Column: &sql.Ident{NamePos: pos(4), Name: "col"},
		})
		AssertParseExpr(t, `"tbl"."col"`, &sql.QualifiedRef{
			Table:  &sql.Ident{NamePos: pos(0), Name: "tbl", Quoted: true},
			Dot:    pos(5),
			Column: &sql.Ident{NamePos: pos(6), Name: "col", Quoted: true},
		})
		AssertParseExpr(t, `schema.tbl.col`, &sql.QualifiedRef{
			Schema:    &sql.Ident{NamePos: pos(0), Name: "schema"},
			SchemaPos: pos(6),
			Table:     &sql.Ident{NamePos: pos(7), Name: "tbl"},
			Dot:       pos(10),
			Column:    &sql.Ident{NamePos: pos(11), Name: "col"},
		})
		AssertParseExpr(t, `"schema"."tbl"."col"`, &sql.QualifiedRef{
			Schema:    &sql.Ident{NamePos: pos(0), Name: "schema", Quoted: true},
			SchemaPos: pos(8),
			Table:     &sql.Ident{NamePos: pos(9), Name: "tbl", Quoted: true},
			Dot:       pos(14),
			Column:    &sql.Ident{NamePos: pos(15), Name: "col", Quoted: true},
		})
		AssertParseExpr(t, `main.vals.a`, &sql.QualifiedRef{
			Schema:    &sql.Ident{NamePos: pos(0), Name: "main"},
			SchemaPos: pos(4),
			Table:     &sql.Ident{NamePos: pos(5), Name: "vals"},
			Dot:       pos(9),
			Column:    &sql.Ident{NamePos: pos(10), Name: "a"},
		})
		AssertParseExprError(t, `tbl.`, `1:4: expected column name, found 'EOF'`)
	})
	t.Run("Exists", func(t *testing.T) {
		AssertParseExpr(t, `EXISTS (SELECT *)`, &sql.Exists{
			Exists: pos(0),
			Lparen: pos(7),
			Select: &sql.SelectStatement{
				Select: pos(8),
				Columns: []*sql.ResultColumn{
					{Star: pos(15)},
				},
			},
			Rparen: pos(16),
		})
		AssertParseExpr(t, `NOT EXISTS (SELECT *)`, &sql.Exists{
			Not:    pos(0),
			Exists: pos(4),
			Lparen: pos(11),
			Select: &sql.SelectStatement{
				Select: pos(12),
				Columns: []*sql.ResultColumn{
					{Star: pos(19)},
				},
			},
			Rparen: pos(20),
		})
		AssertParseExprError(t, `NOT`, `1:3: expected expression, found 'EOF'`)
		AssertParseExprError(t, `EXISTS`, `1:6: expected left paren, found 'EOF'`)
		AssertParseExprError(t, `EXISTS (`, `1:8: expected SELECT or VALUES, found 'EOF'`)
		AssertParseExprError(t, `EXISTS (SELECT`, `1:14: expected expression, found 'EOF'`)
		AssertParseExprError(t, `EXISTS (SELECT *`, `1:16: expected right paren, found 'EOF'`)
	})
	t.Run("BinaryExpr", func(t *testing.T) {
		AssertParseExpr(t, `1 + 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.PLUS,
			Y: &sql.NumberLit{ValuePos: pos(4), Value: "2"},
		})
		AssertParseExpr(t, `1 - 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.MINUS,
			Y: &sql.NumberLit{ValuePos: pos(4), Value: "2"},
		})
		AssertParseExpr(t, `1 * 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.STAR,
			Y: &sql.NumberLit{ValuePos: pos(4), Value: "2"},
		})
		AssertParseExpr(t, `1 / 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.SLASH,
			Y: &sql.NumberLit{ValuePos: pos(4), Value: "2"},
		})
		AssertParseExpr(t, `1 % 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.REM,
			Y: &sql.NumberLit{ValuePos: pos(4), Value: "2"},
		})
		AssertParseExpr(t, `1 || 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.CONCAT,
			Y: &sql.NumberLit{ValuePos: pos(5), Value: "2"},
		})
		AssertParseExpr(t, `1 << 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.LSHIFT,
			Y: &sql.NumberLit{ValuePos: pos(5), Value: "2"},
		})
		AssertParseExpr(t, `1 >> 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.RSHIFT,
			Y: &sql.NumberLit{ValuePos: pos(5), Value: "2"},
		})
		AssertParseExpr(t, `1 & 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.BITAND,
			Y: &sql.NumberLit{ValuePos: pos(4), Value: "2"},
		})
		AssertParseExpr(t, `1 | 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.BITOR,
			Y: &sql.NumberLit{ValuePos: pos(4), Value: "2"},
		})
		AssertParseExpr(t, `1 < 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.LT,
			Y: &sql.NumberLit{ValuePos: pos(4), Value: "2"},
		})
		AssertParseExpr(t, `1 <= 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.LE,
			Y: &sql.NumberLit{ValuePos: pos(5), Value: "2"},
		})
		AssertParseExpr(t, `1 > 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.GT,
			Y: &sql.NumberLit{ValuePos: pos(4), Value: "2"},
		})
		AssertParseExpr(t, `1 >= 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.GE,
			Y: &sql.NumberLit{ValuePos: pos(5), Value: "2"},
		})
		AssertParseExpr(t, `1 = 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.EQ,
			Y: &sql.NumberLit{ValuePos: pos(4), Value: "2"},
		})
		AssertParseExpr(t, `1 != 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.NE,
			Y: &sql.NumberLit{ValuePos: pos(5), Value: "2"},
		})
		AssertParseExpr(t, `(1 + 2)'`, &sql.ParenExpr{
			Lparen: pos(0),
			X: &sql.BinaryExpr{
				X:     &sql.NumberLit{ValuePos: pos(1), Value: "1"},
				OpPos: pos(3), Op: sql.PLUS,
				Y: &sql.NumberLit{ValuePos: pos(5), Value: "2"},
			},
			Rparen: pos(6),
		})
		AssertParseExprError(t, `(`, `1:1: expected expression, found 'EOF'`)
		// A parenthesized expression must be closed; stray tokens are an error.
		AssertParseExprError(t, `(1 2)`, `1:4: expected right paren, found 2`)
		AssertParseExprError(t, `(1`, `1:2: expected right paren, found 'EOF'`)
		AssertParseStatementError(t, `SELECT (1 2`, `1:11: expected right paren, found 2`)
		AssertParseExpr(t, `1 IS 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.IS,
			Y: &sql.NumberLit{ValuePos: pos(5), Value: "2"},
		})
		AssertParseExpr(t, `1 IS NOT 2'`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.ISNOT,
			Y: &sql.NumberLit{ValuePos: pos(9), Value: "2"},
		})
		// IS [NOT] DISTINCT FROM is a null-safe (in)equality comparison.
		AssertParseExpr(t, `1 IS DISTINCT FROM 2`, &sql.BinaryExpr{
			X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
			OpPos: pos(2), Op: sql.ISDISTINCT,
			Y: &sql.NumberLit{ValuePos: pos(19), Value: "2"},
		})
		AssertParseExpr(t, `1 IS NOT DISTINCT FROM 2 AND 3`, &sql.BinaryExpr{
			X: &sql.BinaryExpr{
				X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
				OpPos: pos(2), Op: sql.ISNOTDISTINCT,
				Y: &sql.NumberLit{ValuePos: pos(23), Value: "2"},
			},
			OpPos: pos(25), Op: sql.AND,
			Y: &sql.NumberLit{ValuePos: pos(29), Value: "3"},
		})
		AssertParseExprError(t, `1 IS DISTINCT 2`, `1:15: expected FROM, found 2`)
		// IS NOT and the NOT-prefixed operators share the precedence of IS/LIKE,
		// so they must not swallow a following AND/OR.
		AssertParseExpr(t, `1 IS NOT 2 AND 3`, &sql.BinaryExpr{
			X: &sql.BinaryExpr{
				X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
				OpPos: pos(2), Op: sql.ISNOT,
				Y: &sql.NumberLit{ValuePos: pos(9), Value: "2"},
			},
			OpPos: pos(11), Op: sql.AND,
			Y: &sql.NumberLit{ValuePos: pos(15), Value: "3"},
		})
		AssertParseExpr(t, `1 NOT LIKE 2 OR 3`, &sql.BinaryExpr{
			X: &sql.BinaryExpr{
				X:     &sql.NumberLit{ValuePos: pos(0), Value: "1"},
				OpPos: pos(2), Op: sql.NOTLIKE,
				Y: &sql.NumberLit{ValuePos: pos(11), Value: "2"},
			},
			OpPos: pos(13), Op: sql.OR,
			Y: &sql.NumberLit{ValuePos: pos(16), Value: "3"},
		})
		AssertParseExpr(t, `1 NOT GLOB 2 AND 3`, &sql.BinaryExpr{
			X: &sql.BinaryExpr{
