// Ensure the parser returns an error on pathologically nested input instead
// of overflowing the stack.
func TestParser_DepthLimit(t *testing.T) {
	t.Run("NestedExprOK", func(t *testing.T) {
		AssertParseStatements(t, `SELECT `+strings.Repeat("(", 900)+`1`+strings.Repeat(")", 900), 1)
	})
	t.Run("NestedExpr", func(t *testing.T) {
		s := `SELECT ` + strings.Repeat("(", 2000) + `1` + strings.Repeat(")", 2000)
		AssertParseStatementsError(t, s, `parse tree is too deep (maximum depth 1000)`)
	})
	t.Run("NestedUnary", func(t *testing.T) {
		s := `SELECT ` + strings.Repeat("NOT ", 2000) + `1`
		AssertParseStatementsError(t, s, `parse tree is too deep (maximum depth 1000)`)
	})
	t.Run("NestedSourceOK", func(t *testing.T) {
		AssertParseStatements(t, `SELECT * FROM `+strings.Repeat("(", 500)+`tbl`+strings.Repeat(")", 500), 1)
	})
	t.Run("NestedSource", func(t *testing.T) {
		s := `SELECT * FROM ` + strings.Repeat("(", 2000) + `tbl` + strings.Repeat(")", 2000)
		AssertParseStatementsError(t, s, `parse tree is too deep (maximum depth 1000)`)
	})

	// The depth counter must reset between statements.
	t.Run("MultipleStatements", func(t *testing.T) {
		stmt := `SELECT ` + strings.Repeat("(", 800) + `1` + strings.Repeat(")", 800) + `; `
		AssertParseStatements(t, strings.Repeat(stmt, 3), 3)
	})
}

// Ensure schema-qualified table-valued functions are accepted where sqlite3
// accepts them: in FROM and as the right hand side of IN. A schema-qualified
// ordinary function call is a syntax error in sqlite3 and is rejected here too.
func TestParser_SchemaQualifiedFunctions(t *testing.T) {
	stmt := ParseStatementOrFail(t, `SELECT 1 FROM main.json_each('[1]') AS j WHERE 2 IN main.tf(3)`).(*sql.SelectStatement)
	if fn, ok := stmt.Source.(*sql.QualifiedTableFunctionName); !ok {
		t.Fatalf("source: expected *sql.QualifiedTableFunctionName, got %T", stmt.Source)
	} else if diff := deepEqual(fn, &sql.QualifiedTableFunctionName{
		Schema: &sql.Ident{Name: "main", NamePos: pos(14)},
		Dot:    pos(18),
		Name:   &sql.Ident{Name: "json_each", NamePos: pos(19)},
		Lparen: pos(28),
		Args:   []sql.Expr{&sql.StringLit{Value: "[1]", ValuePos: pos(29)}},
		Rparen: pos(34),
		As:     pos(36),
		Alias:  &sql.Ident{Name: "j", NamePos: pos(39)},
	}); diff != "" {
		t.Fatal(diff)
	}
	if in, ok := stmt.WhereExpr.(*sql.BinaryExpr); !ok || in.Op != sql.IN {
		t.Fatalf("where: expected IN expression, got %s", stmt.WhereExpr.String())
	} else if diff := deepEqual(in.Y, &sql.Call{
		Schema: &sql.Ident{Name: "main", NamePos: pos(52)},
		Dot:    pos(56),
		Name:   &sql.Ident{Name: "tf", NamePos: pos(57)},
		Lparen: pos(59),
		Args:   []sql.Expr{&sql.NumberLit{Value: "3", ValuePos: pos(60)}},
		Rparen: pos(61),
	}); diff != "" {
		t.Fatal(diff)
	}
	if got, want := stmt.String(), `SELECT 1 FROM "main"."json_each"('[1]') AS "j" WHERE 2 IN "main".tf(3)`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}

	AssertParseStatementError(t, `SELECT main.func(1)`, `1:17: expected semicolon or EOF, found '('`)

	// Plain column references are unaffected.
	AssertParseExpr(t, `tbl.col`, &sql.QualifiedRef{
		Table:  &sql.Ident{Name: "tbl", NamePos: pos(0)},
		Dot:    pos(3),
		Column: &sql.Ident{Name: "col", NamePos: pos(4)},
	})
}

// Ensure schema-qualified object names are accepted wherever SQLite allows them.
func TestParser_SchemaQualifiedNames(t *testing.T) {
	for _, tt := range []struct {
		s      string
		schema func(sql.Statement) (*sql.Ident, *sql.Ident)
	}{
		{`CREATE VIEW main.v AS SELECT 1`, func(st sql.Statement) (*sql.Ident, *sql.Ident) {
			v := st.(*sql.CreateViewStatement)
			return v.Schema, v.Name
		}},
		{`CREATE TRIGGER main.trg BEFORE DELETE ON t BEGIN SELECT 1; END`, func(st sql.Statement) (*sql.Ident, *sql.Ident) {
			v := st.(*sql.CreateTriggerStatement)
			return v.Schema, v.Name
		}},
		{`DROP TRIGGER IF EXISTS main.trg`, func(st sql.Statement) (*sql.Ident, *sql.Ident) {
			v := st.(*sql.DropTriggerStatement)
			return v.Schema, v.Name
		}},
		{`ANALYZE main.t`, func(st sql.Statement) (*sql.Ident, *sql.Ident) {
			v := st.(*sql.AnalyzeStatement)
			return v.Schema, v.Name
		}},
		{`DROP VIEW IF EXISTS main.v`, func(st sql.Statement) (*sql.Ident, *sql.Ident) {
			v := st.(*sql.DropViewStatement)
			return v.Schema, v.Name
		}},
		{`CREATE TRIGGER trg AFTER INSERT ON main.t BEGIN SELECT 1; END`, func(st sql.Statement) (*sql.Ident, *sql.Ident) {
			v := st.(*sql.CreateTriggerStatement)
			return v.TableSchema, v.Table
		}},
	} {
		stmt, err := sql.NewParser(strings.NewReader(tt.s)).ParseStatement()
		if err != nil {
			t.Errorf("%s: %v", tt.s, err)
			continue
		}
		schema, name := tt.schema(stmt)
		if schema == nil || schema.Name != "main" {
			t.Errorf("%s: schema=%v, want main", tt.s, schema)
		} else if name == nil || name.Name == "main" {
			t.Errorf("%s: name=%v", tt.s, name)
		}
		// Round trip.
		if stmt2, err := sql.NewParser(strings.NewReader(stmt.String())).ParseStatement(); err != nil {
			t.Errorf("%s: cannot re-parse %q: %v", tt.s, stmt.String(), err)
		} else if stmt2.String() != stmt.String() {
			t.Errorf("%s: unstable: %q != %q", tt.s, stmt.String(), stmt2.String())
		}
	}
}

// Ensure virtual table module arguments accept the forms FTS5 and other
// modules use: a column with a type-like word (UNINDEXED), a quoted or string
// name, an option assigned a function-call value, and no arguments at all.
func TestParser_ModuleArguments(t *testing.T) {
	// A real FTS5 declaration that sqlite3 executes, as does its String().
	stmt := ParseStatementOrFail(t, `CREATE VIRTUAL TABLE ft USING fts5(a UNINDEXED, 'b c', tokenize=porter, prefix='2 3')`).(*sql.CreateVirtualTableStatement)
	if len(stmt.Arguments) != 4 {
		t.Fatalf("expected 4 arguments, got %d", len(stmt.Arguments))
	}
	if got := stmt.Arguments[0].Type.Name.Name; got != "UNINDEXED" {
		t.Errorf("arg 0 type=%q, want UNINDEXED", got)
	}
	if got := stmt.Arguments[1].Name.Name; got != "b c" {
		t.Errorf("arg 1 name=%q, want %q", got, "b c")
	}
	if _, ok := stmt.Arguments[2].Literal.(*sql.Ident); !ok {
		t.Errorf("arg 2 value=%T, want *sql.Ident", stmt.Arguments[2].Literal)
	}
	if got, want := stmt.String(), `CREATE VIRTUAL TABLE "ft" USING "fts5" (a UNINDEXED,"b c",tokenize="porter",prefix='2 3')`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
	if _, err := sql.NewParser(strings.NewReader(stmt.String())).ParseStatement(); err != nil {
		t.Fatalf("cannot re-parse %q: %v", stmt.String(), err)
	}
	// An empty argument list (dbstat takes none).
	stmt = ParseStatementOrFail(t, `CREATE VIRTUAL TABLE s USING dbstat()`).(*sql.CreateVirtualTableStatement)
	if len(stmt.Arguments) != 0 || stmt.String() != `CREATE VIRTUAL TABLE "s" USING "dbstat" ()` {
		t.Fatalf("unexpected: %s", stmt.String())
	}
	// R*Tree auxiliary columns are introduced by a "+" prefix.
	stmt = ParseStatementOrFail(t, `CREATE VIRTUAL TABLE r USING rtree(id, minX, maxX, +label TEXT, +other)`).(*sql.CreateVirtualTableStatement)
	if len(stmt.Arguments) != 5 || !stmt.Arguments[3].Plus.IsValid() || stmt.Arguments[3].Name.Name != "label" || stmt.Arguments[3].Type.Name.Name != "TEXT" || !stmt.Arguments[4].Plus.IsValid() {
		t.Fatalf("unexpected rtree arguments: %s", stmt.String())
	}
	if got, want := stmt.String(), `CREATE VIRTUAL TABLE "r" USING "rtree" (id,minX,maxX,+label TEXT,+other)`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
	// An option whose value is a call parses as a Call.
	stmt = ParseStatementOrFail(t, `CREATE VIRTUAL TABLE vtbl USING mdl(c=d(e))`).(*sql.CreateVirtualTableStatement)
	if _, ok := stmt.Arguments[0].Literal.(*sql.Call); !ok {
		t.Errorf("value=%T, want *sql.Call", stmt.Arguments[0].Literal)
	}
}

// Ensure a string literal is accepted as a column or table alias, as sqlite3
// allows (as ::= AS nm | ids, where ids includes STRING).
func TestParser_StringAlias(t *testing.T) {
	stmt := ParseStatementOrFail(t, `SELECT x 'lbl', y AS 'lbl2' FROM t 'a' JOIN json_each('[1]') 'j'`).(*sql.SelectStatement)
	if diff := deepEqual(stmt.Columns[0].Alias, &sql.Ident{Name: "lbl", NamePos: pos(9), Quoted: true}); diff != "" {
		t.Fatal(diff)
	}
	if diff := deepEqual(stmt.Columns[1].Alias, &sql.Ident{Name: "lbl2", NamePos: pos(21), Quoted: true}); diff != "" {
		t.Fatal(diff)
	}
	join := stmt.Source.(*sql.JoinClause)
	if alias := join.X.(*sql.QualifiedTableName).Alias; alias == nil || alias.Name != "a" {
		t.Fatalf("table alias=%v, want a", alias)
	}
	if alias := join.Y.(*sql.QualifiedTableFunctionName).Alias; alias == nil || alias.Name != "j" {
		t.Fatalf("table function alias=%v, want j", alias)
	}
	if got, want := stmt.String(), `SELECT "x" AS "lbl", "y" AS "lbl2" FROM "t" AS "a" JOIN "json_each"('[1]') AS "j"`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
}

// Ensure a bind parameter prefix without a name is rejected.
func TestParser_EmptyBindName(t *testing.T) {
	AssertParseStatementError(t, `SELECT $`, `1:8: expected expression, found 'ILLEGAL'`)
	AssertParseStatementError(t, `SELECT * FROM t WHERE x = :`, `1:27: expected expression, found 'ILLEGAL'`)
}

// Ensure HAVING is accepted without GROUP BY, as SQLite 3.39+ allows.
func TestParser_HavingWithoutGroupBy(t *testing.T) {
	stmt := ParseStatementOrFail(t, `SELECT count(*) FROM t HAVING count(*) > 1`).(*sql.SelectStatement)
	if stmt.HavingExpr == nil || stmt.GroupByExprs != nil {
		t.Fatalf("expected HAVING without GROUP BY, got %s", stmt.String())
	}
	if got, want := stmt.String(), `SELECT count(*) FROM "t" HAVING count(*) > 1`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
}

// Ensure empty statements (stray semicolons) are skipped, as sqlite3 does.
func TestParser_EmptyStatements(t *testing.T) {
	AssertParseStatements(t, `;`, 0)
	AssertParseStatements(t, `;;`, 0)
	AssertParseStatements(t, `SELECT 1;; SELECT 2`, 2)
	AssertParseStatements(t, `; SELECT 1;`, 1)
}

func TestParser_Vacuum(t *testing.T) {
	AssertParseStatement(t, `VACUUM`, &sql.VacuumStatement{Vacuum: pos(0)})
	AssertParseStatement(t, `VACUUM main`, &sql.VacuumStatement{Vacuum: pos(0), Schema: &sql.Ident{Name: "main", NamePos: pos(7)}})
	AssertParseStatement(t, `VACUUM INTO 'f'`, &sql.VacuumStatement{Vacuum: pos(0), Into: pos(7), Filename: &sql.StringLit{Value: "f", ValuePos: pos(12)}})
	AssertParseStatement(t, `VACUUM main INTO 'f'`, &sql.VacuumStatement{
		Vacuum:   pos(0),
		Schema:   &sql.Ident{Name: "main", NamePos: pos(7)},
		Into:     pos(12),
		Filename: &sql.StringLit{Value: "f", ValuePos: pos(17)},
	})
	AssertParseStatementError(t, `VACUUM INTO`, "1:11: expected expression, found 'EOF'")
}

func TestParser_Attach(t *testing.T) {
	AssertParseStatement(t, `ATTACH 'f' AS d`, &sql.AttachStatement{
		Attach: pos(0),
		Expr:   &sql.StringLit{Value: "f", ValuePos: pos(7)},
		As:     pos(11),
		Schema: &sql.Ident{Name: "d", NamePos: pos(14)},
	})
	AssertParseStatement(t, `ATTACH DATABASE 'f' AS d KEY 'k'`, &sql.AttachStatement{
		Attach:   pos(0),
		Database: pos(7),
		Expr:     &sql.StringLit{Value: "f", ValuePos: pos(16)},
		As:       pos(20),
		Schema:   &sql.Ident{Name: "d", NamePos: pos(23)},
		Key:      pos(25),
		KeyExpr:  &sql.StringLit{Value: "k", ValuePos: pos(29)},
	})
	AssertParseStatementError(t, `ATTACH 'f'`, "1:10: expected AS, found 'EOF'")
	AssertParseStatementError(t, `ATTACH 'f' AS`, "1:13: expected schema name, found 'EOF'")
}

func TestParser_Detach(t *testing.T) {
	AssertParseStatement(t, `DETACH d`, &sql.DetachStatement{Detach: pos(0), Schema: &sql.Ident{Name: "d", NamePos: pos(7)}})
	AssertParseStatement(t, `DETACH DATABASE d`, &sql.DetachStatement{Detach: pos(0), Database: pos(7), Schema: &sql.Ident{Name: "d", NamePos: pos(16)}})
	AssertParseStatementError(t, `DETACH`, "1:6: expected schema name, found 'EOF'")
}

// Ensure the SELECT of an INSERT may itself begin with a WITH clause.
func TestParser_InsertWithSelect(t *testing.T) {
	stmt := ParseStatementOrFail(t, `INSERT INTO t (x) WITH c AS (SELECT 1) SELECT * FROM c`).(*sql.InsertStatement)
	if stmt.Select == nil || stmt.Select.WithClause == nil || len(stmt.Select.WithClause.CTEs) != 1 {
		t.Fatalf("expected select with one CTE, got %s", stmt.String())
	}
	if got, want := stmt.String(), `INSERT INTO "t" ("x") WITH "c" AS (SELECT 1) SELECT * FROM "c"`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
}

// Ensure an INSERT may carry several ON CONFLICT clauses. Only the last may
// omit the conflict target, as in sqlite3.
func TestParser_MultipleUpsertClauses(t *testing.T) {
	stmt := ParseStatementOrFail(t, `INSERT INTO t VALUES (1, 2) ON CONFLICT (x) DO NOTHING ON CONFLICT (y) DO UPDATE SET x = 1 ON CONFLICT DO NOTHING`).(*sql.InsertStatement)
	if len(stmt.UpsertClauses) != 3 {
		t.Fatalf("expected 3 upsert clauses, got %d", len(stmt.UpsertClauses))
	}
	if got, want := stmt.String(), `INSERT INTO "t" VALUES (1, 2) ON CONFLICT ("x") DO NOTHING ON CONFLICT ("y") DO UPDATE SET "x" = 1 ON CONFLICT DO NOTHING`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
	if c := stmt.Clone(); len(c.UpsertClauses) != 3 || c.UpsertClauses[0] == stmt.UpsertClauses[0] {
		t.Fatal("Clone() did not deep copy upsert clauses")
	}
	AssertParseStatementError(t, `INSERT INTO t VALUES (1) ON CONFLICT DO NOTHING ON CONFLICT (x) DO NOTHING`, `1:49: expected semicolon or EOF, found 'ON'`)
}

// Ensure ORDER BY and LIMIT are rejected directly after a VALUES clause, as
// sqlite3 does, while still being accepted after a compound ending in SELECT.
func TestParser_ValuesOrderByLimit(t *testing.T) {
	AssertParseStatementError(t, `VALUES (1) ORDER BY 1`, `1:12: expected semicolon or EOF, found 'ORDER'`)
	AssertParseStatementError(t, `VALUES (1) LIMIT 1`, `1:12: expected semicolon or EOF, found 'LIMIT'`)
	AssertParseStatementError(t, `SELECT 1 UNION VALUES (2) LIMIT 1`, `1:27: expected semicolon or EOF, found 'LIMIT'`)
	stmt := ParseStatementOrFail(t, `VALUES (1), (2) UNION ALL SELECT 3 ORDER BY 1 LIMIT 2`)
	if got, want := stmt.String(), `VALUES (1), (2) UNION ALL SELECT 3 ORDER BY 1 LIMIT 2`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
}

// Ensure TCL-style bind parameters with "::" and "(...)" suffixes parse.
func TestParser_TclBindParameters(t *testing.T) {
	AssertParseExpr(t, `$v::int`, &sql.BindExpr{Name: "$v::int", NamePos: pos(0)})
	stmt := ParseStatementOrFail(t, `SELECT $v::int, $v(1) FROM t`)
	if got, want := stmt.String(), `SELECT $v::int, $v(1) FROM "t"`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
}

// Ensure COLLATE clauses may be chained, as sqlite3 allows.
func TestParser_ChainedCollate(t *testing.T) {
	AssertParseExpr(t, `x COLLATE NOCASE COLLATE BINARY`, &sql.CollateExpr{
		X: &sql.CollateExpr{
			X:         &sql.Ident{Name: "x", NamePos: pos(0)},
			Collation: &sql.CollationClause{Collate: pos(2), Name: &sql.Ident{Name: "NOCASE", NamePos: pos(10)}},
		},
		Collation: &sql.CollationClause{Collate: pos(17), Name: &sql.Ident{Name: "BINARY", NamePos: pos(25)}},
	})
	stmt := ParseStatementOrFail(t, `SELECT x COLLATE NOCASE COLLATE BINARY FROM t`)
	if got, want := stmt.String(), `SELECT "x" COLLATE "NOCASE" COLLATE "BINARY" FROM "t"`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
}

// Ensure identifiers may contain non-ASCII characters and '$', as in SQLite.
func TestParser_NonASCIIIdents(t *testing.T) {
	stmt := ParseStatementOrFail(t, `SELECT 日本語, café, a$b FROM (SELECT 1 AS 日本語, 2 AS café, 3 AS a$b)`).(*sql.SelectStatement)
	if got, want := stmt.String(), `SELECT "日本語", "café", "a$b" FROM (SELECT 1 AS "日本語", 2 AS "café", 3 AS "a$b")`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
	AssertParseExpr(t, `ü`, &sql.Ident{Name: "ü", NamePos: pos(0)})
}

// Ensure a CONSTRAINT name with no constraint after it is accepted (SQLite
// ignores it) rather than crashing the parser, and that a name followed by
// something that is not a constraint is a parse error.
func TestParser_EmptyConstraint(t *testing.T) {
	stmt := ParseStatementOrFail(t, `CREATE TABLE tbl (col1 INTEGER CONSTRAINT c, col2 CONSTRAINT d NOT NULL, CONSTRAINT e)`).(*sql.CreateTableStatement)
	if diff := deepEqual(stmt.Columns[0].Constraints, []sql.Constraint{
		&sql.EmptyConstraint{Constraint: pos(31), Name: &sql.Ident{Name: "c", NamePos: pos(42)}},
	}); diff != "" {
		t.Fatal(diff)
	}
	if diff := deepEqual(stmt.Columns[1].Constraints, []sql.Constraint{
		&sql.NotNullConstraint{Constraint: pos(50), Name: &sql.Ident{Name: "d", NamePos: pos(61)}, Not: pos(63), Null: pos(67)},
	}); diff != "" {
		t.Fatal(diff)
	}
	if diff := deepEqual(stmt.Constraints, []sql.Constraint{
		&sql.EmptyConstraint{Constraint: pos(73), Name: &sql.Ident{Name: "e", NamePos: pos(84)}},
	}); diff != "" {
		t.Fatal(diff)
	}
	if got, want := stmt.String(), `CREATE TABLE "tbl" ("col1" INTEGER CONSTRAINT "c", "col2" CONSTRAINT "d" NOT NULL, CONSTRAINT "e")`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
	AssertParseStatementError(t, `CREATE TABLE tbl (col1 INTEGER CONSTRAINT c FOO)`, `1:45: expected PRIMARY KEY, NOT NULL, UNIQUE, CHECK, DEFAULT, COLLATE, REFERENCES, or GENERATED, found FOO`)
	AssertParseStatementError(t, `CREATE TABLE tbl (col1, CONSTRAINT c FOO)`, `1:38: expected PRIMARY KEY, UNIQUE, CHECK, or FOREIGN KEY, found FOO`)
}

// Ensure a DEFAULT value may be a bare identifier, which SQLite stores as a
// string: `DEFAULT abc` is the same as `DEFAULT 'abc'`.
func TestParser_DefaultIdent(t *testing.T) {
	stmt := ParseStatementOrFail(t, `CREATE TABLE tbl (col1 TEXT DEFAULT abc, col2 TEXT DEFAULT key)`).(*sql.CreateTableStatement)
	if diff := deepEqual(stmt.Columns[0].Constraints[0], &sql.DefaultConstraint{
		Default: pos(28),
		Expr:    &sql.Ident{NamePos: pos(36), Name: "abc"},
	}); diff != "" {
		t.Fatal(diff)
	}
	if got, want := stmt.String(), `CREATE TABLE "tbl" ("col1" TEXT DEFAULT abc, "col2" TEXT DEFAULT key)`; got != want {
		t.Fatalf("String()=%s, want %s", got, want)
	}
	AssertParseStatementError(t, `CREATE TABLE tbl (col1 TEXT DEFAULT)`, `1:36: expected literal value, identifier or left paren, found ')'`)
}

// Ensure type names may be quoted identifiers, string literals or fallback
// keywords, as sqlite3 allows (typename ::= ids | typename ids).
func TestParser_TypeNames(t *testing.T) {
	for _, tt := range []struct{ s, typ string }{
		{`CREATE TABLE tbl (col1 "my type")`, "my type"},
		{`CREATE TABLE tbl (col1 'my type')`, "my type"},
		{"CREATE TABLE tbl (col1 `bt type`(10))", "bt type"},
		{`CREATE TABLE tbl (col1 key)`, "key"},
		{`CREATE TABLE tbl (col1 INTEGER key)`, "INTEGER key"},
		{`CREATE TABLE tbl (col1 UNSIGNED BIG INT NOT NULL)`, "UNSIGNED BIG INT"},
	} {
		stmt := ParseStatementOrFail(t, tt.s).(*sql.CreateTableStatement)
		if len(stmt.Columns) != 1 {
			t.Errorf("%s: expected 1 column, got %d", tt.s, len(stmt.Columns))
		} else if got := stmt.Columns[0].Type.Name.Name; got != tt.typ {
			t.Errorf("%s: type=%q, want %q", tt.s, got, tt.typ)
		}
		if _, err := sql.NewParser(strings.NewReader(stmt.String())).ParseStatement(); err != nil {
			t.Errorf("%s: cannot re-parse %q: %v", tt.s, stmt.String(), err)
		}
	}
	// GENERATED starts a constraint and is never part of a type name.
	stmt := ParseStatementOrFail(t, `CREATE TABLE tbl (col1 INTEGER GENERATED ALWAYS AS (1), col2)`).(*sql.CreateTableStatement)
	if got := stmt.Columns[0].Type.Name.Name; got != "INTEGER" {
		t.Errorf("type=%q, want INTEGER", got)
	} else if len(stmt.Columns[0].Constraints) != 1 {
		t.Errorf("expected generated constraint, got %v", stmt.Columns[0].Constraints)
	}
	// The type of a CAST may be empty, as sqlite3 allows.
	AssertParseExpr(t, `CAST(1 AS)`, &sql.CastExpr{
		Cast:   pos(0),
		Lparen: pos(4),
		X:      &sql.NumberLit{Value: "1", ValuePos: pos(5)},
		As:     pos(7),
		Rparen: pos(9),
	})
	if e, err := sql.NewParser(strings.NewReader(`CAST(1 AS "weird type")`)).ParseExpr(); err != nil {
		t.Fatal(err)
	} else if got := e.(*sql.CastExpr).Type.Name.Name; got != "weird type" {
		t.Errorf("CAST type=%q, want %q", got, "weird type")
	}
}

// Ensure rowid and fallback keywords are accepted as column names after a dot
// and in INSERT column lists, as sqlite3 does.
func TestParser_RowidAndKeywordColumns(t *testing.T) {
	AssertParseExpr(t, `t.rowid`, &sql.QualifiedRef{
		Table:  &sql.Ident{Name: "t", NamePos: pos(0)},
		Dot:    pos(1),
		Column: &sql.Ident{Name: "rowid", NamePos: pos(2)},
	})
	AssertParseExpr(t, `main.t.key`, &sql.QualifiedRef{
		Schema:    &sql.Ident{Name: "main", NamePos: pos(0)},
		SchemaPos: pos(4),
		Table:     &sql.Ident{Name: "t", NamePos: pos(5)},
		Dot:       pos(6),
		Column:    &sql.Ident{Name: "key", NamePos: pos(7)},
	})
	for _, s := range []string{
		`INSERT INTO t (rowid, x) VALUES (1, 2)`,
		`UPDATE t SET rowid = 1`,
		`SELECT t.rowid, t.key FROM t`,
	} {
		stmt, err := sql.NewParser(strings.NewReader(s)).ParseStatement()
		if err != nil {
			t.Errorf("%s: %v", s, err)
		} else if _, err := sql.NewParser(strings.NewReader(stmt.String())).ParseStatement(); err != nil {
			t.Errorf("%s: cannot re-parse %q: %v", s, stmt.String(), err)
		}
	}
}

// Ensure names that are not SQLite keywords can be used as identifiers.
func TestParser_NonKeywordIdents(t *testing.T) {
	for _, s := range []string{
		`SELECT vector, span, truth FROM tbl`,
		`SELECT function, register, variable FROM tbl`,
		`CREATE TABLE tbl (vector BLOB, strict INTEGER, stored TEXT)`,
		`SELECT * FROM vector WHERE span > 1`,
		`SELECT [a b], [c] FROM [my table]`,
	} {
		stmt, err := sql.NewParser(strings.NewReader(s)).ParseStatement()
		if err != nil {
			t.Errorf("%s: %v", s, err)
		} else if _, err := sql.NewParser(strings.NewReader(stmt.String())).ParseStatement(); err != nil {
			t.Errorf("%s: cannot re-parse %q: %v", s, stmt.String(), err)
		}
	}
}

// Ensure operators that are not valid binary operators are rejected rather
// than accepted as expressions that cannot be re-serialized.
func TestParser_InvalidBinaryOp(t *testing.T) {
	AssertParseStatementError(t, `SELECT 1 ~ 2`, `1:10: expected semicolon or EOF, found '~'`)
	AssertParseStatementError(t, `SELECT 1 ESCAPE 2`, `1:10: expected semicolon or EOF, found 'ESCAPE'`)
	AssertParseStatementError(t, `SELECT * FROM tbl WHERE x = 'y' ESCAPE '@'`, `1:33: expected semicolon or EOF, found 'ESCAPE'`)
}

func TestError_Error(t *testing.T) {

// ParseStatementOrFail parses a statement from s. Fail on error.
func ParseStatementOrFail(tb testing.TB, s string) sql.Statement {
	tb.Helper()
	stmt, err := sql.NewParser(strings.NewReader(s)).ParseStatement()
	if err != nil {
		tb.Fatal(err)
	}
	return stmt
}

// AssertParseStatement asserts the value of the first parse of s.
func AssertParseStatement(tb testing.TB, s string, want sql.Statement) {
	tb.Helper()
	stmt, err := sql.NewParser(strings.NewReader(s)).ParseStatement()
	if err != nil {
		tb.Fatal(err)
	} else if diff := deep.Equal(stmt, want); diff != nil {
		tb.Fatalf("mismatch:\n%s", strings.Join(diff, "\n"))
	}
}

// AssertParseStatementError asserts s parses to a given error string.
func AssertParseStatementError(tb testing.TB, s string, want string) {
	tb.Helper()
	_, err := sql.NewParser(strings.NewReader(s)).ParseStatement()
	if err == nil || err.Error() != want {
		tb.Fatalf("ParseStatement()=%q, want %q", err, want)
	}
}

// AssertParseStatements asserts the count of statements parsed from s.
func AssertParseStatements(tb testing.TB, s string, wantCount int) {
	tb.Helper()
	stmts, err := sql.NewParser(strings.NewReader(s)).ParseStatements()
	if err != nil {
		tb.Fatal(err)
	} else if len(stmts) != wantCount {
		tb.Fatalf("ParseStatements()=%d statements, want %d", len(stmts), wantCount)
	}
}

// AssertParseStatementsError asserts s parses to a given error substring.
func AssertParseStatementsError(tb testing.TB, s string, wantSubstring string) {
	tb.Helper()
	_, err := sql.NewParser(strings.NewReader(s)).ParseStatements()
	if err == nil {
		tb.Fatal("ParseStatements() expected error, got nil")
	}
	if !strings.Contains(err.Error(), wantSubstring) {
		tb.Fatalf("ParseStatements() error=%q, want error containing %q", err, wantSubstring)
	}
}

// ParseExprOrFail parses a expression from s. Fail on error.
func ParseExprOrFail(tb testing.TB, s string) sql.Expr {
	tb.Helper()
	stmt, err := sql.NewParser(strings.NewReader(s)).ParseExpr()
	if err != nil {
		tb.Fatal(err)
	}
	return stmt
}

// AssertParseExpr asserts the value of the first parse of s.
func AssertParseExpr(tb testing.TB, s string, want sql.Expr) {
	tb.Helper()
	stmt, err := sql.NewParser(strings.NewReader(s)).ParseExpr()
	if err != nil {
		tb.Fatal(err)
	} else if diff := deep.Equal(stmt, want); diff != nil {
		tb.Fatalf("mismatch:\n%s", strings.Join(diff, "\n"))
	}
}

// AssertParseExprError asserts s parses to a given error string.
func AssertParseExprError(tb testing.TB, s string, want string) {
	tb.Helper()
	_, err := sql.NewParser(strings.NewReader(s)).ParseExpr()
	if err == nil || err.Error() != want {
		tb.Fatalf("ParseExpr()=%q, want %q", err, want)
	}
}

// pos is a helper function for generating positions based on offset for one-line parsing.
func pos(offset int) sql.Pos {
	return sql.Pos{Offset: offset, Line: 1, Column: offset + 1}
}

func deepEqual(a, b interface{}) string {
	return strings.Join(deep.Equal(a, b), "\n")
}

func Benchmark_NewParser(b *testing.B) {
	s := `SELECT * FROM foo WHERE bar = 1 AND baz > 2 ORDER BY qux DESC LIMIT 10`
	for i := 0; i < b.N; i++ {
		parser := sql.NewParser(strings.NewReader(s))
		_, err := parser.ParseStatement()
		if err != nil {
			b.Fatal(err)
		}
	}
}

