package sql

import (
	"strings"
	"testing"
)

func TestReturningIdempotence(t *testing.T) {
	cases := []string{
		`DELETE FROM tbl LIMIT returning RETURNING id`,
		`INSERT INTO tbl(x) VALUES (1) ON CONFLICT DO UPDATE SET x=1 RETURNING id, id AS returning`,
		`UPDATE tbl SET returning = 1 RETURNING returning`,
		`DELETE FROM tbl ORDER BY returning LIMIT 5 RETURNING *`,
		`INSERT INTO tbl(x) VALUES (3) RETURNING id AS returning`,
		`SELECT 1 AS returning`,
	}
	for _, c := range cases {
		s1, err := NewParser(strings.NewReader(c)).ParseStatement()
		if err != nil {
			t.Fatalf("first parse %q: %v", c, err)
		}
		out1 := s1.String()
		s2, err := NewParser(strings.NewReader(out1)).ParseStatement()
		if err != nil {
			t.Fatalf("re-parse %q: %v", out1, err)
		}
		if out2 := s2.String(); out1 != out2 {
			t.Errorf("not idempotent:\n  %q\n  %q", out1, out2)
		}
	}
}
EOF
